def count_nums(arr):
    count = 0
    for num in arr:
        if num == 0:
            continue
        # Treat negative numbers: first digit is negative, rest positive
        num_str = str(num)
        if num_str[0] == '-':
            # e.g. '-123' -> signed digits: -1, 2, 3 → sum = -1+2+3 = 4
            digit_sum = -int(num_str[1]) + sum(int(d) for d in num_str[2:])
        else:
            digit_sum = sum(int(d) for d in num_str)

        if digit_sum > 0:
            count += 1
    return count
