def count_nums(arr):
    def digit_sum(num):
        if num == 0:
            return 0
        if num < 0:
            num = -num
            # 第一个数字为负
            first = True
            total = 0
            for ch in str(num):
                digit = int(ch)
                if first:
                    total -= digit
                    first = False
                else:
                    total += digit
            return total
        else:
            return sum(int(d) for d in str(num))

    count = 0
    for x in arr:
        if digit_sum(x) > 0:
            count += 1
    return count
